    def _g(self, key, ch):
        t = GLYPHS[key]
        return t.get(ch) or t.get("?"), (ch if ch in t else "?")

    def width(self, s, key, size, ls=0.0):
        return sum(self._g(key, c)[0][0] * size / 1000 + ls for c in s) - ls if s else 0.0

    def wrap(self, s, key, size, maxw, ls=0.0):
        lines, cur = [], ""
        for word in s.split():
            t = (cur + " " + word).strip()
            if self.width(t, key, size, ls) <= maxw: cur = t
            else: lines.append(cur); cur = word
        return lines + ([cur] if cur else [])

    def put(self, s, key, size, x, y, cls, ls=0.0, anchor="start"):
        wd = self.width(s, key, size, ls)
        if anchor == "middle": x -= wd / 2
        elif anchor == "end": x -= wd
        k, cx, out = size / 1000, x, []
        for c in s:
            (adv, d), real = self._g(key, c)
            if d:
                gk = f"{key}_{ord(real):x}"
                self.used[gk] = d
                out.append(f'<use href="#g{gk}" transform="translate({cx:.2f} {y:.2f}) scale({k:.5f})"/>')
            cx += adv * k + ls
        return f'<g class="{cls}">' + "".join(out) + "</g>"

    def defs(self):
        return "<defs>" + "".join(f'<path id="g{k}" d="{d}"/>' for k, d in self.used.items()) + "</defs>"
